package cli

import "strings"

// The ring statement grammar lives in this file and nowhere else. Every other
// piece (the parser, 'help', Tab completion, the refusal-fix guard) is
// generated by walking ringForms, so a word cannot drift from the grammar.
// Sources: entry-ring-conventions 17 (the grammar), entry-ring-queries-and-clients
// 1, 5 and 7 (the statements and their help).

// ringElemKind is the class of one pattern element.
type ringElemKind int

const (
	elemLit ringElemKind = iota
	elemArg
	elemOpt
	elemFlag
)

// ringArgKind is how an argument's tokens are read and where completion finds its names.
type ringArgKind int

const (
	kNewName    ringArgKind = iota // a name being created
	kDatabase                      // an existing database
	kBucket                        // an existing bucket of the database
	kStoreField                    // a declared store field of the bucket
	kNewNode                       // a node id being introduced
	kMember                        // an existing member node id
	kInt                           // a non-negative number
	kSlot                          // a slot, 0 to 8191, in decimal or as 0x hex
	kHex                           // a hex cursor
	kQuotedID                      // a document id in double quotes
	kAnyID                         // a document id, bare or in double quotes
	kAddr                          // host:port
	kChoice                        // one of a fixed set of words
	kFields                        // { Field type, ... } of a create bucket
	kChanges                       // { add Field type, drop Field } of an alter bucket

	// kDatabaseOptions is { replication_factor: <n>, storage: disk } of create database and alter database
	kDatabaseOptions
	kDoc      // a document literal
	kValues   // a comma-separated literal list
	kTopic    // the words of a help topic
	kUser     // a user name, bare or in double quotes
	kRoleSpec // <role> or <role>@<database>, where the database may be *
	kRoles    // [<role>@<db>, ...] of a create user or alter user
)

// ringElem is one element of a form's pattern.
type ringElem struct {
	kind    ringElemKind
	text    string      // elemLit: the token; elemFlag: the switch, such as --clear
	name    string      // elemArg: the Statement argument name; elemFlag: its name
	arg     ringArgKind // elemArg
	show    string      // elemArg: how the syntax line prints it
	choices []string    // kChoice
	keys    []string    // kDoc: top-level keys completion offers
	opt     []ringElem  // elemOpt
}

func rLit(text string) ringElem { return ringElem{kind: elemLit, text: text} }

func rArg(name string, kind ringArgKind, show string) ringElem {
	return ringElem{kind: elemArg, name: name, arg: kind, show: show}
}

func rChoice(name, show string, words ...string) ringElem {
	return ringElem{kind: elemArg, name: name, arg: kChoice, show: show, choices: words}
}

func rDoc(keys ...string) ringElem {
	return ringElem{kind: elemArg, name: "doc", arg: kDoc, show: "{…}", keys: keys}
}

func rOpt(elems ...ringElem) ringElem { return ringElem{kind: elemOpt, opt: elems} }

func rFlag(name, text string) ringElem { return ringElem{kind: elemFlag, name: name, text: text} }

// ringExample is one runnable statement. Note is the right-hand column of a
// topic page and may be empty.
type ringExample struct{ Text, Note string }

// exs wraps plain statements as examples without notes.
func exs(texts ...string) []ringExample {
	out := make([]ringExample, len(texts))
	for i, text := range texts {
		out[i] = ringExample{Text: text}
	}
	return out
}

// ringForm is one row of the grammar table: one statement.
type ringForm struct {
	// Verb names the form in Statement.Verb.
	Verb string
	// Group is the heading 'help all' lists the form under.
	Group string
	// Pattern is the token pattern the parser matches and the syntax line prints.
	Pattern []ringElem
	// Short is the one line of the 'help all' column, written to fit beside the syntax in 80 columns.
	Short string
	// Heading names the form on a topic page that holds several forms; it
	// defaults to Short.
	Heading string
	// Long is the paragraph of the statement's topic page.
	Long string
	// Spec is the section of the entry-ring specs that owns the form.
	Spec string
	// Examples are runnable statements; Examples[0] is the headline that parse
	// errors quote and topic pages lead with. Tests parse and run each.
	Examples []ringExample
	// Next is the last line of the topic page: a runnable statement or 'help <word>'.
	Next string
	// Familiar is an optional line for a reader who knows MongoDB or MySQL.
	Familiar string
	// Fixes are the forms of this statement that refusal texts quote, with
	// <placeholders>; the guard parses, completes and finds each in help.
	Fixes []string
	// Unavailable marks a form that parses, so a refusal's quoted fix can be
	// checked and the statement gets a clear refusal, but that the ring wire
	// cannot run yet: the default 'help' and Tab completion leave it out, and
	// 'help <word>' says it is not available yet.
	Unavailable bool
	// NeedsDB is true when the statement runs against a database the line may
	// leave out because 'use <db>' selected one.
	NeedsDB bool
}

// Syntax renders the form's pattern as the line 'help' prints.
func (f ringForm) Syntax() string { return ringJoin(ringSyntaxTokens(f.Pattern)) }

// ringVerb is one store verb: the single source of the verb's help page, its
// syntax, the store types it runs on and the ones the wire cannot carry yet.
// ringUnwiredStoreVerb reads NotYet, so a help page and a refusal cannot disagree.
type ringVerb struct {
	// Name is the verb as typed; Args is its argument list as help prints it.
	Name, Args string
	// Types are the store words the verb runs on; NotYet are the store words
	// the wire cannot carry the verb for yet. Any other store word is refused
	// by the server, which names the verbs that store takes.
	Types, NotYet []string
	// Title is the page's heading phrase; Short is the types-table phrase;
	// Long is the one-sentence meaning.
	Title, Short, Long string
	// Notes follows the example; Instead points at the verb to use on the
	// store types this one does not run on.
	Notes, Instead string
	// Example is a statement against the User bucket of the quick start;
	// Before is a statement that must run first for the example to answer;
	// Result is the first line the example prints after Before.
	Example, Before, Result string
	// Next is the last line of the page.
	Next string
	// Follows names the verb whose result this verb acts on (ack follows
	// claim); 'help types' lists a store's leading verbs and leaves these out.
	Follows string
}

