// ringVerbNames lists the store verbs in table order.
func ringVerbNames() []string {
	names := make([]string, len(ringVerbs))
	for i, verb := range ringVerbs {
		names[i] = verb.Name
	}
	return names
}

// ringVerbExamples are the verbs' examples, in table order: the examples of the 'field' form.
func ringVerbExamples() []ringExample {
	out := make([]ringExample, len(ringVerbs))
	for i, verb := range ringVerbs {
		out[i] = ringExample{Text: verb.Example}
	}
	return out
}

// ringVerbByName finds a store verb by its name.
func ringVerbByName(name string) (ringVerb, bool) {
	for _, verb := range ringVerbs {
		if verb.Name == name {
			return verb, true
		}
	}
	return ringVerb{}, false
}

// ringQuick is one line of the Quick Start page.
type ringQuick struct {
	// Heading starts a new section when it is not empty.
	Heading string
	// Example must be the Text of an example of a form or a ringVerb.
	Example string
	// Note is the right-hand column.
	Note string
}

