func ringInDB() ringElem { return rOpt(rLit("in"), rArg("database", kDatabase, "<db>")) }

// ringTarget is the 'db.<bucket>' head of the keyed forms.
func ringTarget() []ringElem {
	return []ringElem{rLit("db"), rLit("."), rArg("bucket", kBucket, "<bucket>")}
}

func ringKeyed() []ringElem {
	return append(ringTarget(), rLit("["), rArg("id", kQuotedID, `"<id>"`), rLit("]"), rLit("."))
}

func ringConcat(parts ...[]ringElem) []ringElem {
	var out []ringElem
	for _, part := range parts {
		out = append(out, part...)
	}
	return out
}

func ringDatabaseOptions() ringElem {
	return rOpt(rArg("options", kDatabaseOptions, "{ <options> }"))
}

func ringMember(verb, short, summary, example string, unavailable bool) ringForm {
	return ringForm{Verb: verb, Short: short, Unavailable: unavailable, Group: "Cluster", Pattern: []ringElem{rLit(verb), rArg("node", kMember, "<node>")},
		Long: summary, Spec: "conventions 17; queries 5", Examples: exs(example), Fixes: []string{verb + " <node>"}}
}

